return ['domain'=>'wpml-import','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'pt_PT','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Um plugin multiusos para exportar e importar conteúdo multilingue.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'O gatilho de importação já não aceita a chave no URL. Envie-a num corpo POST.','Method Not Allowed'=>'Método não permitido','Unauthorized'=>'Não autorizado','No items to process'=>'Sem itens para processar','No Content'=>'Sem conteúdo','Import process completed'=>'Processo de importação concluído','Success'=>'Sucesso','Import process failed'=>'O processo de importação falhou','Internal Server Error'=>'Erro interno do servidor','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d item não pôde ser processado e foi ignorado.' . "\0" . '%1$s: %2$d itens não puderam ser processados e foram ignorados.','Cleaning Up Post Data'=>'Limpeza de dados de artigos','Removing temporary and import-related post meta data.'=>'A remover metadados temporários e de importação dos artigos.','Cleaning Up Term Data'=>'Limpeza de dados de termos','Removing temporary and import-related term meta data.'=>'A remover metadados de termos temporários e relacionados com a importação.','Connecting Post Image Attachments'=>'A ligar anexos de imagem de artigos','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'A atualizar os IDs de anexos de miniaturas e galerias em artigos, produtos e tipos de conteúdo personalizados traduzidos para apontarem para os seus equivalentes traduzidos.','Connecting Inline Term Translations'=>'A ligar traduções de termos inline','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'A analisar artigos com um único termo de taxonomia para identificar e ligar os termos atribuídos a estes artigos com as suas traduções.','Deleting Obsolete Original Terms'=>'A eliminar termos originais obsoletos','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'A remover termos originais que já não são necessários após a criação de duplicados para termos com o mesmo nome. A garantir que nenhuns artigos estão ligados a estes termos originais.','Duplicating Terms with Shared Names Across Languages'=>'A duplicar termos com nomes partilhados entre idiomas','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'A criar duplicados no idioma correto para termos que partilham o mesmo nome entre idiomas, mas que pertencem a artigos em idiomas diferentes.','Fixing Imported Post Slugs'=>'A corrigir slugs de artigos importados','Regenerating translated post slugs to prevent conflicts with the originals.'=>'A regenerar slugs de artigos traduzidos para evitar conflitos com os originais.','Clearing Translations Cache'=>'A limpar a cache de traduções','Invalidating the persistent cache so it can be regenerated.'=>'A invalidar a cache persistente para que possa ser regenerada.','Marking Parent Terms for Connection'=>'A marcar termos ascendentes para ligação','Collecting parent terms to connect their translations in the next step.'=>'A recolher termos ascendentes para ligar as suas traduções no próximo passo.','Connecting Posts with Correct Term Translations'=>'A ligar artigos com as traduções de termos corretas','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'A garantir que os artigos estão ligados a termos no idioma correto, especialmente se tiver os mesmos nomes de termos em vários idiomas.','Sending Posts for Automatic Translation'=>'A enviar artigos para tradução automática','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'A criar trabalhos de tradução automática para artigos marcados para tradução automática nos dados exportados.','Setting Attachments\' Language'=>'A definir o idioma dos anexos','Assigning a language to imported attachments.'=>'A atribuir um idioma aos anexos importados.','Updating Final Post Status'=>'A atualizar o estado final do artigo','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'A definir o estado do artigo com base no campo “_wpml_import_after_process_post_status” do ficheiro de importação (se fornecido).','Identifying Inline Term Languages'=>'A identificar idiomas de termos inline','Identifying and setting the language of terms created during post imports.'=>'A identificar e a definir o idioma dos termos criados durante a importação de artigos.','Setting Posts’ Language'=>'A definir o idioma dos artigos','Connecting posts to the default language and translations.'=>'A ligar artigos ao idioma predefinido e às traduções.','Setting Terms’ Language'=>'A definir o idioma dos termos','Connecting taxonomy terms to the default (original) language and translations.'=>'A ligar termos de taxonomia ao idioma predefinido (original) e às traduções.','Setting Parent Terms\' Language'=>'A definir o idioma dos termos ascendentes','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'A atribuir idioma a termos de taxonomia ascendentes que não têm um, com base no idioma atribuído aos seus descendentes.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'A migrar o seu site multilingue? Lembre-se de instalar também o %s no seu novo site antes de importar o seu conteúdo para que possamos restaurar todas as traduções.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'A migrar a sua loja multilingue? Com o %1$s e o %2$s pode transferir o seu conteúdo traduzido para um novo site, incluindo vendas cruzadas, vendas sugeridas e atributos de produto.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'A migrar a sua loja multilingue? Lembre-se de instalar o %1$s e o %2$s no seu novo site antes de importar o seu conteúdo para que possamos restaurar todas as traduções.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'Deseja importar o seu conteúdo multilingue? Lembre-se de instalar o %s no seu site original antes de exportar o seu conteúdo para que possamos importar todas as traduções aqui.','Looking to import your multilingual content? Install %1$s on this site.'=>'Deseja importar o seu conteúdo multilingue? Instale o %1$s neste site.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Lembre-se de ativar também o %2$s e o %3$s na sua loja original antes de exportar o seu conteúdo para que possamos importar todas as traduções aqui.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'Deseja importar o seu conteúdo multilingue? Lembre-se de ativar o %1$s e o %2$s na sua loja original antes de exportar o seu conteúdo para que possamos importar todas as traduções aqui.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Mudar para todos os idiomas','Linking Product Attribute Translations'=>'A associar traduções de atributos de produto','Connecting product attributes to their translations based on associated product variations.'=>'A ligar atributos de produto às suas traduções com base nas variações de produto associadas.','Updating Related Products On Translations'=>'A atualizar produtos relacionados nas traduções','Setting up-sells, cross-sells and grouped products references in the right language.'=>'A configurar referências de vendas sugeridas, vendas cruzadas e produtos agrupados no idioma correto.','Importing Custom Attribute Labels'=>'A importar etiquetas de atributos personalizados','Importing labels for product-specific (custom) attributes from the exported data.'=>'A importar etiquetas para atributos específicos do produto (personalizados) a partir dos dados exportados.','You are about to export all your products in all languages at once.'=>'Está prestes a exportar todos os seus produtos em todos os idiomas de uma só vez.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Lembre-se de instalar o %1$s e o %2$s no seu novo site antes de importar o seu conteúdo para que possamos restaurar todas as traduções.','You are about to export your products in %s.'=>'Está prestes a exportar os seus produtos em %s.','Registering Product Attributes'=>'A registar atributos de produto','Identifying and registering attributes created during product imports for translation.'=>'A identificar e a registar atributos criados durante a importação de produtos para tradução.','Identifying Product Attribute Languages'=>'A identificar idiomas de atributos de produto','Identifying and setting the language of attributes created during product imports.'=>'A identificar e a definir o idioma dos atributos criados durante a importação de produtos.','Export and Import'=>'Exportar e importar','I’m using the built-in %s export/import tool'=>'Estou a utilizar a ferramenta de exportação/importação nativa do %s','I’m using %s plugin'=>'Estou a utilizar o plugin %s','(%1$d/%2$d items)'=>'(%1$d/%2$d itens)','%d skipped'=>'%d ignorados','(no items)'=>'(sem itens)','Counting items...'=>'A contar itens...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Primeiro, diga-nos como vai criar o conteúdo que irá importar:','Continue'=>'Continuar','I’m using %1$s and %2$s plugins'=>'Estou a utilizar os plugins %1$s e %2$s','I’m using a different method to export from this site'=>'Estou a utilizar um método diferente para exportar deste site','I’m exporting the content from this site'=>'Estou a exportar o conteúdo deste site','I’m exporting the content from a different website or system'=>'Estou a exportar o conteúdo de um site ou sistema diferente','Before importing, add language columns to your content'=>'Antes de importar, adicione colunas de idioma ao seu conteúdo','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Certifique-se de que o seu ficheiro de importação inclui as seguintes colunas (campos personalizados) com informações de idioma:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: Um valor que é o mesmo para todas as traduções de cada item. Em sites de e-commerce, este será frequentemente o SKU.','%s: The language code for each item.'=>'%s: O código de idioma para cada item.','And, you can include these two columns if needed:'=>'E pode incluir estas duas colunas, se necessário:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: Se este item for uma tradução, defina esta coluna com o código do idioma de origem. Se não for uma tradução, mantenha-a vazia.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: Defina como “draft” ou “published” para determinar o estado de publicação do artigo após o ajuste dos idiomas. Normalmente, este valor será “published”.','Here is an example of importing two items, into your site’s languages (%s):'=>'Aqui está um exemplo de importação de dois itens para os idiomas do seu site (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'Depois de adicionar as colunas de idioma ao seu ficheiro de conteúdo multilingue, importe-o para o seu site utilizando qualquer plugin de importação da sua preferência.','Before importing, your content needs language information'=>'Antes de importar, o seu conteúdo necessita de informações de idioma','%s will add the necessary language information to your export.'=>'O %s adicionará as informações de idioma necessárias à sua exportação.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Importe o seu ficheiro de conteúdo multilingue para o site utilizando qualquer plugin de importação da sua preferência.','Use your favorite import plugin'=>'Utilize o seu plugin de importação favorito','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'Depois de importar o conteúdo, este ainda não apresentará as informações de idioma corretas. Por isso, recomendamos que importe novo conteúdo como rascunhos. Se estiver a importar atualizações, pode manter o conteúdo já publicado como publicado.','Return here, to %s, to set languages and connect translations'=>'Regresse aqui, ao %s, para definir idiomas e ligar traduções','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'Ao visitar esta página depois de ter importado conteúdo com informações de idioma, poderá executar o %s para aplicar idiomas e ligar traduções.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'Já importou e continua a ver este ecrã? %1$sResolução de problemas %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'Como exportar e importar conteúdo em vários idiomas','%s is ready to update your imported content'=>'O %s está pronto para atualizar o seu conteúdo importado','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Bom trabalho. Detetámos %1$d termos e %2$d artigos que foram importados e necessitam de informações de idioma.','Good job. We see %d terms that are imported and need language information.'=>'Bom trabalho. Detetámos %d termos que foram importados e necessitam de informações de idioma.','Good job. We see %d posts that are imported and need language information.'=>'Bom trabalho. Detetámos %d artigos que foram importados e necessitam de informações de idioma.','Run WPML Import'=>'Executar o WPML Import','Multilingual Import Complete'=>'Importação multilingue concluída']];